import os, strutils, tables, times, json

proc analyzeLogs(dir: string): JsonNode =
  var hourly = initCountTable[string]()
  for file in walkDirRec(dir):
    if not file.endsWith(".log"):
      continue
    for line in lines(file):
      # e.g. [2023-10-24 14:32:11] ERROR Something went wrong
      if line.startsWith("[") and "]" in line:
        let parts = line.split("]", 1)
        if parts.len == 2:
          let timestampStr = parts[0][1..^1] # remove [
          let rest = parts[1].strip()
          let logParts = rest.split(' ', 1)
          if logParts.len == 2:
            let level = logParts[0]
            if level == "ERROR":
              try:
                let dt = parse(timestampStr, "yyyy-MM-dd HH:mm:ss")
                hourly.inc(dt.format("yyyy-MM-dd HH"))
              except TimeParseError:
                discard

  var j = newJObject()
  for k, v in hourly:
    j[k] = %v
  result = %*{"hourly_errors": j}

