proc aggregateRevenue(csvData: string): string =
  var s = newStringStream(csvData)
  var p: CsvParser
  p.open(s, "sales.csv")
  p.readHeaderRow()

  var revenueByCategory = initTable[string, float]()

  while p.readRow():
    let category = p.rowEntry("Category")
    let priceStr = p.rowEntry("Price")
    let qtyStr = p.rowEntry("Quantity")

    try:
      let revenue = parseFloat(priceStr) * parseFloat(qtyStr)
      revenueByCategory[category] = revenueByCategory.getOrDefault(category, 0.0) + revenue
    except ValueError:
      continue

  p.close()

  var j = newJObject()
  for k, v in revenueByCategory:
    j[k] = newJFloat(v)

  result = j.pretty()

