import streams, strutils, os, tables

proc processConfig(inputPath, outputPath: string) =
  var inStream = newFileStream(inputPath, fmRead)
  if inStream.isNil:
    raise newException(IOError, "Cannot open input config")

  var outStream = newFileStream(outputPath, fmWrite)
  if outStream.isNil:
    inStream.close()
    raise newException(IOError, "Cannot open output config")

  defer:
    inStream.close()
    outStream.close()

  for line in inStream.lines():
    let trimmed = line.strip()
    if trimmed.startsWith(";") or trimmed.len == 0:
      outStream.writeLine(line)
      continue

    if trimmed.startsWith("[") and trimmed.endsWith("]"):
      outStream.writeLine(line)
      continue

    let parts = trimmed.split('=', 1)
    if parts.len == 2:
      let key = parts[0].strip()
      var val = parts[1].strip()

      if val.startsWith("${") and val.endsWith("}"):
        let envVar = val[2..^2]
        val = getEnv(envVar, "DEFAULT_VAL")

      outStream.writeLine(key & " = " & val)
    else:
      outStream.writeLine(line)

