import strutils, tables, sequtils

proc renderTemplate(tmpl: string, vars: Table[string, string]): string =
  var res = ""
  var i = 0
  while i < tmpl.len:
    if i + 1 < tmpl.len and tmpl[i] == '{' and tmpl[i+1] == '{':
      let closeIdx = tmpl.find("}}", i)
      if closeIdx != -1:
        let key = tmpl[i+2 ..< closeIdx]
        if vars.hasKey(key):
          let val = vars[key]
          try:
            let numVal = parseFloat(val)
            res &= formatFloat(numVal, ffDecimal, 2)
          except ValueError:
            res &= val
        else:
          echo "WARNING: Missing key '", key, "' in template variables."
          res &= "{{" & key & "}}"
        i = closeIdx + 2
        continue
    res.add(tmpl[i])
    inc i
  return res

