proc extractAbsoluteUrls(markdown: string): string =
  var uniqueUrls = initHashSet[string]()

  var i = 0
  while i < markdown.len:
    if markdown[i] == '[':
      let closeBracket = markdown.find(']', i)
      if closeBracket != -1 and closeBracket + 1 < markdown.len and markdown[closeBracket + 1] == '(':
        let closeParen = markdown.find(')', closeBracket + 1)
        if closeParen != -1:
          let rawUrl = markdown[closeBracket + 2 ..< closeParen].strip()
          try:
            let parsed = parseUri(rawUrl)
            if parsed.scheme.len > 0 and parsed.hostname.len > 0:
              uniqueUrls.incl(rawUrl)
          except ValueError:
            discard
          i = closeParen
    inc i

  var urlArray = newJArray()
  for u in uniqueUrls:
    urlArray.add(%u)

  result = $(%*{"absolute_links": urlArray})

