proc processAccessLog(logData: string): string =
  var statusCounts = initCountTable[int]()
  let staticExts = @[".png", ".jpg", ".css", ".js", ".ico"]

  for line in logData.splitLines():
    let parts = line.split()
    if parts.len < 9: continue

    var path = ""
    var statusStr = ""
    for i, p in parts:
      if p.startsWith("\"GET") or p.startsWith("\"POST") or p.startsWith("\"PUT") or p.startsWith("\"DELETE"):
        if i + 1 < parts.len:
          path = parts[i + 1]
        if i + 3 < parts.len:
          statusStr = parts[i + 3]
        break

    if path.len > 0 and statusStr.len > 0:
      let isStatic = staticExts.anyIt(path.endsWith(it))
      if not isStatic:
        try:
          let status = parseInt(statusStr)
          statusCounts.inc(status)
        except ValueError:
          discard

  var report = "Access Log Summary:\n"
  report &= "-------------------\n"
  for status, count in statusCounts:
    report &= "Status " & $status & ": " & $count & " requests\n"

  return report

