proc collectTodos(dir: string): JsonNode =
  var devTasks = initTable[string, seq[string]]()

  for path in walkDirRec(dir):
    if not path.endsWith(".nim") and not path.endsWith(".c") and not path.endsWith(".cpp"):
      continue

    try:
      for line in lines(path):
        let idx = line.find("// TODO(")
        if idx != -1:
          let closeIdx = line.find("):", idx)
          if closeIdx != -1:
            let dev = line[idx + 8 ..< closeIdx].toLowerAscii()
            let task = line[closeIdx + 2 .. ^1].strip()

            if not devTasks.hasKey(dev):
              devTasks[dev] = @[]
            devTasks[dev].add(task & " (in " & extractFilename(path) & ")")
    except IOError:
      continue

  var j = newJObject()
  for dev, tasks in devTasks:
    var jTasks = newJArray()
    for t in tasks:
      jTasks.add(%t)
    j[dev] = jTasks

  result = j

