import json, strutils, algorithm

type SemVer = object
  major, minor, patch: int
  prerelease: string

proc parseSemVer(s: string): SemVer =
  let cleanS = if s.startsWith("v"): s[1..^1] else: s
  let parts = cleanS.split('-', 1)
  let mainVer = parts[0].split('.')

  if mainVer.len != 3:
    raise newException(ValueError, "Invalid SemVer: " & s)

  result.major = parseInt(mainVer[0])
  result.minor = parseInt(mainVer[1])
  result.patch = parseInt(mainVer[2])

  if parts.len == 2:
    result.prerelease = parts[1]
  else:
    result.prerelease = ""

proc cmp(a, b: SemVer): int =
  if a.major != b.major: return cmp(a.major, b.major)
  if a.minor != b.minor: return cmp(a.minor, b.minor)
  if a.patch != b.patch: return cmp(a.patch, b.patch)

  if a.prerelease == "" and b.prerelease != "": return 1
  if a.prerelease != "" and b.prerelease == "": return -1
  return cmp(a.prerelease, b.prerelease)

proc findHighestVersion(jsonInput: string): string =
  let arr = parseJson(jsonInput)
  var versions: seq[SemVer] = @[]

  for node in arr:
    try:
      versions.add(parseSemVer(node.getStr()))
    except ValueError:
      continue

  versions.sort(cmp)
  if versions.len > 0:
    let highest = versions[^1]
    result = $highest.major & "." & $highest.minor & "." & $highest.patch
    if highest.prerelease.len > 0:
      result &= "-" & highest.prerelease
  else:
    result = "None"

