proc maskEmails(text: string, allowedDomains: HashSet[string]): string =
  var resultText = text
  let words = text.splitWhitespace()

  for word in words:
    let cleanWord = word.strip(chars = PunctuationChars)
    if "@" in cleanWord:
      let parts = cleanWord.split('@')
      if parts.len == 2 and "." in parts[1]:
        let localPart = parts[0]
        let domainPart = parts[1]
        let fullMatch = localPart & "@" & domainPart

        var replacement = ""
        if domainPart in allowedDomains:
          replacement = repeat('*', localPart.len) & "@" & domainPart
        else:
          replacement = "[REDACTED]"

        resultText = resultText.replace(fullMatch, replacement)

  return resultText

