proc normalizePhones(inputJson: string): string =
  let data = parseJson(inputJson)
  if data.kind != JObject:
    return "{}"

  var cleanedData = newJObject()

  for key, val in data.pairs:
    if val.kind == JString:
      let rawNum = val.getStr()

      var justDigits = ""
      for c in rawNum:
        if c in {'0'..'9', '+'}:
          justDigits.add(c)

      if not justDigits.startsWith("+"):
        justDigits = "+" & justDigits

      var isValid = justDigits.len > 1 and justDigits.len <= 16
      for i in 1..<justDigits.len:
        if justDigits[i] notin {'0'..'9'}: isValid = false

      if isValid:
        cleanedData[key] = %justDigits
      else:
        cleanedData[key] = %"INVALID"
    else:
      cleanedData[key] = val

  return cleanedData.pretty()

