proc convertXmlToJson(xmlPath: string): JsonNode =
  var s = newFileStream(xmlPath, fmRead)
  if s.isNil:
    return newJNull()
  defer: s.close()

  let root = parseXml(s)

  proc parseNode(n: XmlNode): JsonNode =
    if n.kind == xnElement:
      var obj = newJObject()
      for child in n:
        if child.kind == xnElement:
          let childJson = parseNode(child)
          let t = child.tag
          if obj.hasKey(t):
            if obj[t].kind != JArray:
              let arr = newJArray()
              arr.add(obj[t])
              obj[t] = arr
            obj[t].add(childJson)
          else:
            obj[t] = childJson
        elif child.kind == xnText:
          return %child.text
      return obj
    return newJNull()

  result = parseNode(root)

