proc formatKeyValuePairs(input: string): string =
  var dict = initOrderedTable[string, string]()

  let pairs = input.split(',')
  for p in pairs:
    let parts = p.split('=', 1)
    if parts.len == 2:
      dict[parts[0].strip()] = parts[1].strip()

  var maxKeyLen = 0
  for k in dict.keys:
    maxKeyLen = max(maxKeyLen, k.len)

  var output = ""
  for k, v in dict:
    output &= k.alignLeft(maxKeyLen + 2) & ": " & v & "\n"

  return output

