proc analyzeHashtags(post: string): seq[string] =
  var counts = initCountTable[string]()

  for word in post.splitWhitespace():
    if word.startsWith("#") and word.len > 1:
      let tag = word[1..^1].toLowerAscii().strip(chars = PunctuationChars)
      counts.inc(tag)

  counts.sort()

  var topTags: seq[string] = @[]
  var i = 0
  for tag, count in counts:
    if i >= 3: break
    topTags.add(tag & " (" & $count & ")")
    inc i

  return topTags

