import json, strutils, math

proc redactIps(eventsJson: string): string =
  let arr = parseJson(eventsJson)
  if arr.kind != JArray:
    return "[]"

  var sanitized = newJArray()

  for event in arr:
    if event.kind == JObject and event.hasKey("message"):
      let msg = event["message"].getStr()
      var words = msg.split()
      for i, w in words:
        let cleanW = w.strip(chars = PunctuationChars)
        let parts = cleanW.split('.')
        if parts.len == 4:
          var isIp = true
          for p in parts:
            try:
              let num = parseInt(p)
              if num < 0 or num > 255: isIp = false
            except ValueError:
              isIp = false
          if isIp:
            words[i] = words[i].replace(cleanW, "[REDACTED IP]")

      let cleanMsg = words.join(" ")

      var newEvent = copy(event)
      newEvent["message"] = %cleanMsg
      sanitized.add(newEvent)
    else:
      sanitized.add(event)

  return sanitized.pretty()

