import strutils, streams, math

proc minifyCss(css: string, outputPath: string) =
  var minified = ""
  var inComment = false
  var i = 0

  while i < css.len:
    if not inComment and i + 1 < css.len and css[i] == '/' and css[i+1] == '*':
      inComment = true
      i += 2
      continue
    if inComment and i + 1 < css.len and css[i] == '*' and css[i+1] == '/':
      inComment = false
      i += 2
      continue

    if not inComment:
      minified.add(css[i])
    inc i

  # Remove newlines and tabs
  minified = minified.replace("\n", "").replace("\r", "").replace("\t", "")

  # Collapse spaces manually
  var collapsed = ""
  var lastWasSpace = false
  for c in minified:
    if c == ' ':
      if not lastWasSpace:
        collapsed.add(c)
        lastWasSpace = true
    else:
      collapsed.add(c)
      lastWasSpace = false

  minified = collapsed

  # Remove spaces around colons, braces
  minified = minified.replace(" { ", "{").replace("{ ", "{").replace(" {", "{")
  minified = minified.replace(" } ", "}").replace("} ", "}").replace(" }", "}")
  minified = minified.replace(" : ", ":").replace(": ", ":").replace(" :", ":")
  minified = minified.replace(" ; ", ";").replace("; ", ";").replace(" ;", ";")

  var fs = newFileStream(outputPath, fmWrite)
  if not fs.isNil:
    fs.write(minified)
    fs.close()
  else:
    echo "Failed to open output file."

