import strutils, sequtils, math

proc countSyllables(word: string): int =
  let w = word.toLowerAscii().strip(chars = PunctuationChars)
  if w.len <= 3: return 1

  var syls = 0
  let vowels = {'a', 'e', 'i', 'o', 'u', 'y'}
  var inVowelGroup = false
  for c in w:
    if c in vowels:
      if not inVowelGroup:
        inc syls
        inVowelGroup = true
    else:
      inVowelGroup = false

  if w.endsWith("e") and not w.endsWith("le"):
    syls -= 1

  if syls <= 0: return 1
  return syls

proc calculateReadability(text: string): float =
  var sentences = 0
  for c in text:
    if c in {'.', '!', '?'}: inc sentences
  if sentences == 0: sentences = 1

  let words = text.splitWhitespace()

  let numSentences = float(sentences)
  let numWords = float(max(1, words.len))

  var totalSyllables = 0
  for w in words:
    totalSyllables += countSyllables(w)

  # Flesch-Kincaid Grade Level formula
  result = 0.39 * (numWords / numSentences) + 11.8 * (float(totalSyllables) / numWords) - 15.59

