proc checkSpelling(dictText, docText: string): seq[string] =
  var validWords = initHashSet[string]()
  for line in dictText.splitLines():
    let w = line.strip().toLowerAscii()
    if w.len > 0:
      validWords.incl(w)

  var errors: seq[string] = @[]

  var lineNum = 1
  for line in docText.splitLines():
    for rawWord in line.splitWhitespace():
      var word = ""
      for c in rawWord:
        if c in {'a'..'z', 'A'..'Z'}:
