proc parseNestedQuery(query: string): JsonNode =
  result = newJObject()

  for pair in query.split('&'):
    if pair.len == 0: continue
    let parts = pair.split('=', 1)
    if parts.len != 2: continue

    let rawKey = decodeUrl(parts[0])
    let val = decodeUrl(parts[1])

    let bracketStart = rawKey.find('[')
    if bracketStart != -1 and rawKey.endsWith("]"):
      let mainKey = rawKey[0 ..< bracketStart]
      let subKey = rawKey[bracketStart + 1 .. ^2]

      if not result.hasKey(mainKey):
        result[mainKey] = newJObject()
      if result[mainKey].kind == JObject:
        result[mainKey][subKey] = %val
    else:
      result[rawKey] = %val

