proc standardizeDates(inputJson: string, dateField: string): string =
  let arr = parseJson(inputJson)
  if arr.kind != JArray: return "[]"

  var resultArr = newJArray()

  # Supported input formats
  let formats = ["yyyy-MM-dd", "dd/MM/yyyy", "MM-dd-yyyy"]

  for item in arr:
    if item.kind == JObject and item.hasKey(dateField):
      let rawDate = item[dateField].getStr()
      var parsedTime: DateTime
      var success = false

      for fmt in formats:
        try:
          parsedTime = parse(rawDate, fmt)
          success = true
          break
        except TimeParseError:
          continue

      var newItem = copy(item)
      if success:
        newItem[dateField] = %parsedTime.format("yyyy-MM-dd'T'HH:mm:ss'Z'")
      else:
        newItem[dateField] = %"INVALID_DATE"

      resultArr.add(newItem)

  return resultArr.pretty()

