proc redactFiles(dir: string, badWords: seq[string]): JsonNode =
  var stats = initTable[string, int]()

  for path in walkDirRec(dir):
    if not path.endsWith(".txt"): continue

    try:
      var content = readFile(path)
      var replacements = 0

      for bad in badWords:
        let searchWord = " " & bad & " "
        var idx = content.find(searchWord)
        while idx != -1:
          inc replacements
          let star = " " & repeat('*', bad.len) & " "
          content = content[0 ..< idx] & star & content[idx + searchWord.len .. ^1]
          idx = content.find(searchWord, idx + star.len)

        # Also check start and end of string, and punctuation boundaries in a real app,
        # but basic replace is fine for demo
        if content.startsWith(bad & " "):
          inc replacements
          content = repeat('*', bad.len) & " " & content[bad.len + 1 .. ^1]

      if replacements > 0:
        writeFile(path, content)
        stats[extractFilename(path)] = replacements
    except IOError:
      continue

  var j = newJObject()
  for file, count in stats:
    j[file] = %count
  return j

