proc classifySentiment(csvData: string): string =
  let posWords = toHashSet(["good", "great", "excellent", "happy", "love"])
  let negWords = toHashSet(["bad", "terrible", "awful", "sad", "hate"])

  var s = newStringStream(csvData)
  var p: CsvParser
  p.open(s, "input.csv")
  p.readHeaderRow()

  var results = newJArray()

  while p.readRow():
    let text = p.rowEntry("Text")
    var posCount = 0
    var negCount = 0

    for word in text.splitWhitespace():
      let w = word.strip(chars = PunctuationChars).toLowerAscii()
      if w in posWords: inc posCount
      elif w in negWords: inc negCount

    var sentiment = "neutral"
    if posCount > negCount: sentiment = "positive"
    elif negCount > posCount: sentiment = "negative"

    var item = newJObject()
    item["text"] = %text
    item["sentiment"] = %sentiment
    results.add(item)

  p.close()
  return results.pretty()

