proc extractImageUrls(html: string, baseUrl: string): string =
  let baseUri = parseUri(baseUrl)
  var urls = newJArray()

  var i = 0
  while i < html.len:
    let idx = html.toLowerAscii().find("<img", i)
    if idx == -1: break

    let endIdx = html.find(">", idx)
    if endIdx != -1:
      let tag = html[idx .. endIdx]
      let srcIdx = tag.toLowerAscii().find("src=")
      if srcIdx != -1:
        let quote = tag[srcIdx + 4]
        if quote == '"' or quote == '\'':
          let srcEnd = tag.find(quote, srcIdx + 5)
          if srcEnd != -1:
            let src = tag[srcIdx + 5 ..< srcEnd]
            try:
              let absoluteUri = baseUri / src
              urls.add(%($absoluteUri))
            except ValueError:
              discard
      i = endIdx + 1
    else:
      break

  return $(%*{"images": urls})

