proc toSnakeCase(s: string): string =
  var res = ""
  for i, c in s:
    if c.isUpperAscii():
      if i > 0 and s[i-1] notin {'_', '-'}:
        # Lookahead for acronyms
        if i + 1 < s.len and s[i+1].isLowerAscii():
          res.add('_')
        elif i > 0 and s[i-1].isLowerAscii():
          res.add('_')
      res.add(c.toLowerAscii())
    else:
      res.add(c)
  return res

