proc extractAndValidateJson(text: string, requiredKeys: HashSet[string]): string =
  let startIdx = text.find("```json")
  if startIdx == -1: return "{}"

  let contentStart = startIdx + 7
  let endIdx = text.find("```", contentStart)
  if endIdx == -1: return "{}"

  let jsonStr = text[contentStart ..< endIdx].strip()

  try:
    let jNode = parseJson(jsonStr)
    var isValid = true
    var missing: seq[string] = @[]

    if jNode.kind == JObject:
      for k in requiredKeys:
        if not jNode.hasKey(k):
