          missing.add(k)

      var res = newJObject()
      res["data"] = jNode
      res["valid"] = %isValid
      res["missing"] = %missing
      return res.pretty()
    else:
      return "{\"error\": \"Root is not an object\"}"
  except JsonParsingError:
    return "{\"error\": \"Invalid JSON\"}"

