proc csvToSqlInsert(csvPath, tableName: string): string =
  var fs = newFileStream(csvPath, fmRead)
  if fs.isNil: return ""
  defer: fs.close()

  var header: seq[string] = @[]
  var values: seq[string] = @[]

  var line = ""
  if fs.readLine(line):
    for h in line.split(','): header.add(h.strip())

  while fs.readLine(line):
    let parts = line.split(',')
    var rowVals: seq[string] = @[]
    for p in parts:
      let clean = p.strip()
      try:
        discard parseFloat(clean)
        rowVals.add(clean)
      except ValueError:
        rowVals.add("'" & clean.replace("'", "''") & "'")
    values.add("(" & rowVals.join(", ") & ")")

  if header.len == 0 or values.len == 0: return ""

  result = "INSERT INTO " & tableName & " (" & header.join(", ") & ") VALUES\n"
  result &= values.join(",\n") & ";"

