  while qIdx < queue.len:
    let path = queue[qIdx]
    inc qIdx
    let node = path[^1]

    if graph.hasKey(node):
      for neighbor in graph[node]:
        if neighbor notin visited:
          var newPath = path
          newPath.add(neighbor)
          if neighbor == target:
            return newPath
          visited.incl(neighbor)
          queue.add(newPath)

  return @[]

