proc jaccardSimilarity(doc1, doc2: string): float =
  var set1 = initHashSet[string]()
  for w in doc1.splitWhitespace():
    let c = w.strip(chars = PunctuationChars).toLowerAscii()
    if c.len > 0: set1.incl(c)

  var set2 = initHashSet[string]()
  for w in doc2.splitWhitespace():
    let c = w.strip(chars = PunctuationChars).toLowerAscii()
    if c.len > 0: set2.incl(c)

  let inter = set1 * set2
  let uni = set1 + set2

  if uni.len == 0: return 1.0
  return float(inter.len) / float(uni.len)

