# We simulate a max heap by negating values
proc addNumber(minH, maxH: var HeapQueue[float], num: float) =
  if maxH.len == 0 or num <= -maxH[0]:
    maxH.push(-num)
  else:
    minH.push(num)

  # Rebalance
  if maxH.len > minH.len + 1:
    let val = -maxH.pop()
    minH.push(val)
  elif minH.len > maxH.len:
    let val = minH.pop()
    maxH.push(-val)

proc getMedian(minH, maxH: HeapQueue[float]): float =
  if maxH.len > minH.len:
    return -maxH[0]
  else:
    return (-maxH[0] + minH[0]) / 2.0

proc trackMedians(stream: seq[float]): string =
  var minHeap = initHeapQueue[float]()
  var maxHeap = initHeapQueue[float]()
  var results = newJArray()

  for n in stream:
    addNumber(minHeap, maxHeap, n)
    results.add(%getMedian(minHeap, maxHeap))

  return results.pretty()

