type LRUCache = object
  capacity: int
  cache: Table[string, string]
  order: seq[string]

proc initLRUCache(cap: int): LRUCache =
  result.capacity = cap
  result.cache = initTable[string, string]()
  result.order = @[]

proc access(c: var LRUCache, key, val: string) =
  if c.cache.hasKey(key):
    # Update value and move to front
    c.cache[key] = val
    let idx = c.order.find(key)
    if idx != -1: c.order.delete(idx)
    c.order.add(key)
  else:
    if c.order.len >= c.capacity:
      let oldest = c.order[0]
      c.order.delete(0)
      c.cache.del(oldest)
    c.cache[key] = val
    c.order.add(key)

proc simulateLRU(requests: seq[tuple[k, v: string]]): JsonNode =
  var lru = initLRUCache(3)
  for req in requests:
    lru.access(req.k, req.v)

  var j = newJObject()
  var orderArr = newJArray()
  for k in lru.order:
    orderArr.add(%k)

  j["keys_in_order"] = orderArr

  var cacheData = newJObject()
  for k, v in lru.cache:
    cacheData[k] = %v
  j["data"] = cacheData

  return j

