proc decryptByFreq(cipherText, freqMapJson: string): string =
  let engFreq = parseJson(freqMapJson)
  var expected: seq[char] = @[]
  for n in engFreq:
    expected.add(n.getStr()[0])

  var counts = initCountTable[char]()
  for c in cipherText:
    if c in {'a'..'z', 'A'..'Z'}:
      counts.inc(c.toLowerAscii())

  counts.sort()

  var cipherOrder: seq[char] = @[]
  for k, v in counts:
    cipherOrder.add(k)

  var decodeMap = initTable[char, char]()
  let limit = min(cipherOrder.len, expected.len)
  for i in 0 ..< limit:
    decodeMap[cipherOrder[i]] = expected[i]

  var plain = ""
  for c in cipherText:
    let isUpper = c.isUpperAscii()
    let lc = c.toLowerAscii()
    if decodeMap.hasKey(lc):
      let pChar = decodeMap[lc]
      plain.add(if isUpper: pChar.toUpperAscii() else: pChar)
    else:
      plain.add(c)

  return plain

