type Cell = tuple[x, y: int]

proc nextGeneration(activeCells: HashSet[Cell]): HashSet[Cell] =
  var neighborCounts = initCountTable[Cell]()

  for cell in activeCells:
    for dx in -1..1:
      for dy in -1..1:
        if dx == 0 and dy == 0: continue
        neighborCounts.inc((x: cell.x + dx, y: cell.y + dy))

  result = initHashSet[Cell]()

  for cell, occCount in neighborCounts:
    if occCount == 3:
      result.incl(cell)
    elif occCount == 2 and cell in activeCells:
      result.incl(cell)

proc simulateLife(gridStr: string, steps: int): string =
  var active = initHashSet[Cell]()
  let lines = gridStr.splitLines()

  for y, line in lines:
    for x, c in line:
      if c == 'O': active.incl((x: x, y: y))

  for _ in 1..steps:
    active = nextGeneration(active)

  var minX, maxX, minY, maxY = 0
  var first = true
  for c in active:
    if first:
      minX = c.x; maxX = c.x
      minY = c.y; maxY = c.y
      first = false
    else:
      if c.x < minX: minX = c.x
      if c.x > maxX: maxX = c.x
      if c.y < minY: minY = c.y
      if c.y > maxY: maxY = c.y

  var outLines: seq[string] = @[]
  for y in minY..maxY:
    var line = ""
    for x in minX..maxX:
      if (x: x, y: y) in active: line.add('O')
      else: line.add('.')
    outLines.add(line)

  return outLines.join("\n")

