type Grid = seq[seq[int]]

proc isValid(g: Grid, r, c, val: int): bool =
  for i in 0..8:
    if g[r][i] == val: return false
    if g[i][c] == val: return false

  let boxR = (r div 3) * 3
  let boxC = (c div 3) * 3
  for i in 0..2:
    for j in 0..2:
      if g[boxR + i][boxC + j] == val: return false

  return true

proc solve(g: var Grid): bool =
  for r in 0..8:
    for c in 0..8:
      if g[r][c] == 0:
        for val in 1..9:
          if isValid(g, r, c, val):
            g[r][c] = val
            if solve(g): return true
            g[r][c] = 0
        return false
  return true

