proc knapsack(itemsJson: string, capacity: int): string =
  let arr = parseJson(itemsJson)
  var weights: seq[int] = @[]
  var values: seq[int] = @[]

  for n in arr:
    weights.add(n["w"].getInt())
    values.add(n["v"].getInt())

  let nItems = weights.len
  var dp = newSeq[seq[int]](nItems + 1)
  for i in 0..nItems: dp[i] = newSeq[int](capacity + 1)

  for i in 1..nItems:
    for w in 1..capacity:
      if weights[i-1] <= w:
        dp[i][w] = max(dp[i-1][w], dp[i-1][w - weights[i-1]] + values[i-1])
      else:
        dp[i][w] = dp[i-1][w]

  var j = newJObject()
  j["max_value"] = %dp[nItems][capacity]
  return j.pretty()

