type
  Pos = tuple[x, y: int]
  Node = object
    p: Pos
    f: int

proc `<`(a, b: Node): bool = a.f < b.f

proc heuristic(a, b: Pos): int =
  abs(a.x - b.x) + abs(a.y - b.y)

proc findPath(gridJson: string, startPos, endPos: Pos): string =
  let gArr = parseJson(gridJson)
  var grid: seq[seq[int]] = @[]
  for r in gArr:
    var row: seq[int] = @[]
    for c in r: row.add(c.getInt())
    grid.add(row)

  var openSet = initHeapQueue[Node]()
  openSet.push(Node(p: startPos, f: heuristic(startPos, endPos)))

  var cameFrom = initTable[Pos, Pos]()
  var gScore = initTable[Pos, int]()
  gScore[startPos] = 0

  let rows = grid.len
  let cols = grid[0].len

  while openSet.len > 0:
    let current = openSet.pop().p
    if current == endPos:
      var path: seq[Pos] = @[current]
      var curr = current
      while cameFrom.hasKey(curr):
        curr = cameFrom[curr]
        path.add(curr)

      var res = newJArray()
      for i in countdown(path.len - 1, 0):
        var jp = newJArray()
        jp.add(%path[i].x)
        jp.add(%path[i].y)
        res.add(jp)
      return res.pretty()

    let dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    for d in dirs:
      let neighbor = (x: current.x + d[0], y: current.y + d[1])
      if neighbor.x >= 0 and neighbor.x < cols and neighbor.y >= 0 and neighbor.y < rows:
        if grid[neighbor.y][neighbor.x] == 1: continue # obstacle

        let tentative = gScore.getOrDefault(current, 99999) + 1
        if tentative < gScore.getOrDefault(neighbor, 99999):
          cameFrom[neighbor] = current
          gScore[neighbor] = tentative
          openSet.push(Node(p: neighbor, f: tentative + heuristic(neighbor, endPos)))

  return "[]"

