proc getPermutations(items: seq[string]): string =
  var results: seq[seq[string]] = @[]
  var current = items

  proc backtrack(startIdx: int) =
    if startIdx == current.len:
      results.add(current)
      return

    for i in startIdx ..< current.len:
      swap(current[startIdx], current[i])
      backtrack(startIdx + 1)
      swap(current[startIdx], current[i])

  backtrack(0)

  var jRes = newJArray()
  for r in results:
    var jArr = newJArray()
    for item in r: jArr.add(%item)
    jRes.add(jArr)

  return jRes.pretty()

