proc simpleHash(s: string): int =
  var h = 0
  for c in s: h = (h * 31 + ord(c)) mod 1000000
  return h

proc simulateConsistentHashing(nodes, keys: seq[string]): string =
  var ring: seq[tuple[hash: int, name: string]] = @[]

  for n in nodes:
    ring.add((hash: simpleHash(n), name: n))

  ring.sort(proc(a, b: tuple[hash: int, name: string]): int = cmp(a.hash, b.hash))

  var routing = initTable[string, seq[string]]()
  for n in nodes: routing[n] = @[]

  for k in keys:
    let kh = simpleHash(k)
    var assignedNode = ring[0].name
    for r in ring:
      if r.hash >= kh:
        assignedNode = r.name
        break
    routing[assignedNode].add(k)

  var jObj = newJObject()
  for k, v in routing:
    var jArr = newJArray()
    for item in v: jArr.add(%item)
    jObj[k] = jArr

  return jObj.pretty()

