proc findTwoSum(dataJson: string, target: int): string =
  let arr = parseJson(dataJson)
  var nums: seq[int] = @[]
  for a in arr: nums.add(a.getInt())

  nums.sort()

  var left = 0
  var right = nums.len - 1
  var pairs = newJArray()

  while left < right:
    let s = nums[left] + nums[right]
    if s == target:
      var pair = newJArray()
      pair.add(%nums[left])
      pair.add(%nums[right])
      pairs.add(pair)
      inc left
      dec right
    elif s < target:
      inc left
    else:
      dec right

  return pairs.pretty()

