proc calculateAbTest(visitorsA, convA, visitorsB, convB: int): string =
  let pA = float(convA) / float(max(1, visitorsA))
  let pB = float(convB) / float(max(1, visitorsB))

  let seA = sqrt(pA * (1.0 - pA) / float(visitorsA))
  let seB = sqrt(pB * (1.0 - pB) / float(visitorsB))

  let diff = pB - pA
  let seDiff = sqrt(seA*seA + seB*seB)

  # Z-score for difference
  var zScore = 0.0
  if seDiff > 0.0: zScore = diff / seDiff

  # Rough 95% CI is 1.96 * seDiff
  let isSignificant = abs(zScore) > 1.96

  var j = newJObject()
  j["rate_A"] = %formatFloat(pA, ffDecimal, 4)
  j["rate_B"] = %formatFloat(pB, ffDecimal, 4)
  j["difference"] = %formatFloat(diff, ffDecimal, 4)
  j["z_score"] = %formatFloat(zScore, ffDecimal, 2)
  j["significant"] = %isSignificant
  return j.pretty()

