type Box = object
  x1, y1, x2, y2: float

proc iou(a, b: Box): float =
  let xLeft = max(a.x1, b.x1)
  let yTop = max(a.y1, b.y1)
  let xRight = min(a.x2, b.x2)
  let yBottom = min(a.y2, b.y2)

  if xRight < xLeft or yBottom < yTop: return 0.0

  let intersectionArea = (xRight - xLeft) * (yBottom - yTop)
  let aArea = (a.x2 - a.x1) * (a.y2 - a.y1)
  let bArea = (b.x2 - b.x1) * (b.y2 - b.y1)

  let iouScore = intersectionArea / (aArea + bArea - intersectionArea)
  return iouScore

proc calculateIouMatrix(boxesJson: string): string =
  let arr = parseJson(boxesJson)
  var boxes: seq[Box] = @[]

  for b in arr:
    boxes.add(Box(
      x1: b[0].getFloat(), y1: b[1].getFloat(),
      x2: b[2].getFloat(), y2: b[3].getFloat()
    ))

  var matrix = newJArray()
  for i in 0 ..< boxes.len:
    var row = newJArray()
    for j in 0 ..< boxes.len:
      let score = iou(boxes[i], boxes[j])
      row.add(%score)
    matrix.add(row)

  return matrix.pretty()

