proc calculateNextExecutions(tasksJson: string): string =
  let arr = parseJson(tasksJson)
  var schedule: seq[tuple[task: string, dt: DateTime]] = @[]

  let now = getTime()
  let localNow = local(now)

  for item in arr:
    let taskName = item["name"].getStr()
    let interval = item["interval"].getStr()

    var nextTime = localNow
    if interval == "hourly":
      nextTime = nextTime + initDuration(hours = 1)
      # Reset minutes/seconds roughly
      let ts = nextTime.format("yyyy-MM-dd HH") & ":00:00"
      nextTime = parse(ts, "yyyy-MM-dd HH:mm:ss")
    elif interval == "daily":
      nextTime = nextTime + initDuration(days = 1)
      let ts = nextTime.format("yyyy-MM-dd") & " 00:00:00"
      nextTime = parse(ts, "yyyy-MM-dd HH:mm:ss")

    schedule.add((task: taskName, dt: nextTime))

  schedule.sort(proc(a, b: tuple[task: string, dt: DateTime]): int =
    if a.dt < b.dt: return -1
    if a.dt > b.dt: return 1
    return 0
  )

  var j = newJArray()
  for s in schedule:
    var jObj = newJObject()
    jObj["task"] = %s.task
    jObj["next_execution"] = %s.dt.format("yyyy-MM-dd HH:mm:ss")
    j.add(jObj)

  return j.pretty()

