proc calculateStats(dataJson: string): string =
  let arr = parseJson(dataJson)
  var values: seq[float] = @[]
  for a in arr: values.add(a.getFloat())

  let n = values.len
  if n == 0: return "{}"

  var sum = 0.0
  for v in values: sum += v
  let mean = sum / float(n)

  var sqSum = 0.0
  for v in values:
    sqSum += pow(v - mean, 2.0)

  let variance = sqSum / float(n)
  let stdDev = sqrt(variance)

  var j = newJObject()
  j["count"] = %n
  j["mean"] = %mean
  j["variance"] = %variance
  j["std_dev"] = %stdDev
  return j.pretty()

