proc evalRpn(tokensJson: string): string =
  let arr = parseJson(tokensJson)
  var stack: seq[float] = @[]

  try:
    for t in arr:
      let token = t.getStr()

      if token == "+":
        let b = stack.pop()
        let a = stack.pop()
        stack.add(a + b)
      elif token == "-":
        let b = stack.pop()
        let a = stack.pop()
        stack.add(a - b)
      elif token == "*":
        let b = stack.pop()
        let a = stack.pop()
        stack.add(a * b)
      elif token == "/":
        let b = stack.pop()
        let a = stack.pop()
        stack.add(a / b)
      elif token == "pow":
        let b = stack.pop()
        let a = stack.pop()
        stack.add(pow(a, b))
      elif token == "sqrt":
        let a = stack.pop()
        stack.add(sqrt(a))
      else:
        stack.add(parseFloat(token))

    var j = newJObject()
    if stack.len == 1:
      j["result"] = %stack[0]
    else:
      j["error"] = %"Invalid expression"
    return j.pretty()
  except CatchableError as e:
    return "{\"error\": \"" & e.msg & "\"}"

