    let daysTotal = dur.inDays()

    # For a more exact breakdown:
    let yDiff = now.year - bDate.year
    let mDiff = int(now.month) - int(bDate.month)
    let dDiff = now.monthday - bDate.monthday

    var years = yDiff
    var months = mDiff
    var days = dDiff

    if days < 0:
      dec months
      days += 30 # Approx
    if months < 0:
      dec years
      months += 12

    var jRes = newJObject()
    jRes["years"] = %years
    jRes["months"] = %months
    jRes["days"] = %days
    jRes["total_days"] = %daysTotal

    return jRes.pretty()
  except TimeParseError:
    return "{\"error\": \"Invalid date\"}"

