proc loadConfiguration(defaultJsonStr, localFilePath: string): string =
  var config = parseJson(defaultJsonStr)

  # Override with Environment Variables
  if config.kind == JObject:
    var keysToUpdate: seq[string] = @[]
    for k in config.keys: keysToUpdate.add(k)

    for k in keysToUpdate:
      let envVal = getEnv("APP_" & k.toUpperAscii())
      if envVal.len > 0:
        if config[k].kind == JInt:
          config[k] = %parseInt(envVal)
        elif config[k].kind == JBool:
          config[k] = %parseBool(envVal)
        else:
          config[k] = %envVal

  # Override with Local File
  if fileExists(localFilePath):
    try:
      let localJson = parseFile(localFilePath)
      if localJson.kind == JObject:
        for k, v in localJson:
          config[k] = copy(v)
    except JsonParsingError:
      discard

  return config.pretty()

