proc pollFileOnce(watchFile, masterLog: string, lastSize: var int64): bool =
  if not fileExists(watchFile): return false

  let currentSize = getFileSize(watchFile)
  if currentSize > lastSize:
    var fsIn = newFileStream(watchFile, fmRead)
    if fsIn.isNil: return false

    fsIn.setPosition(lastSize)
    let newData = fsIn.readAll()
    fsIn.close()

    var fsOut = newFileStream(masterLog, fmAppend)
    if not fsOut.isNil:
      let ts = format(getTime(), "yyyy-MM-dd HH:mm:ss")
      for line in newData.splitLines():
        if line.len > 0:
          fsOut.writeLine("[" & ts & "] " & line)
      fsOut.close()

    lastSize = currentSize
    return true
  return false

