proc batchRename(dir, ext, prefix: string): string =
  var log = newJArray()
  var counter = 1

  let searchPattern = dir / "*." & ext

  for path in walkFiles(searchPattern):
    let newName = prefix & "_" & intToStr(counter).align(3, '0') & "." & ext
    let newPath = dir / newName

    try:
      moveFile(path, newPath)
      var entry = newJObject()
      entry["old"] = %extractFilename(path)
      entry["new"] = %newName
      log.add(entry)
      inc counter
    except OSError:
      continue

  return log.pretty()

