proc buildUrl(baseUrl, paramsJson: string): string =
  var u = parseUri(baseUrl)
  let params = parseJson(paramsJson)

  var queryParts: seq[string] = @[]

  if params.kind == JObject:
    for k, v in params:
      let valStr = if v.kind == JString: v.getStr() else: $v
      queryParts.add(encodeUrl(k) & "=" & encodeUrl(valStr))

  if queryParts.len > 0:
    if u.query.len > 0:
      u.query = u.query & "&" & queryParts.join("&")
    else:
      u.query = queryParts.join("&")

  return $u

