proc downloadFileChunks(url, destPath: string) =
  var client = newHttpClient()
  defer: client.close()

  var fsOut = newFileStream(destPath, fmWrite)
  if fsOut.isNil: return
  defer: fsOut.close()

  try:
    let resp = client.request(url, HttpGet)
    if resp.code.int == 200:
      let stream = resp.bodyStream
      var buffer = newString(8192)
      var total = 0
      while true:
        let bytesRead = stream.readData(addr buffer[0], 8192)
        if bytesRead > 0:
          fsOut.writeData(addr buffer[0], bytesRead)
          total += bytesRead
        if bytesRead < 8192:
          break
      echo "Downloaded ", total, " bytes."
    else:
      echo "Failed with status: ", resp.status
  except CatchableError:
    echo "Network error."

