    let parts = header.split(';')
    if parts.len > 0:
      let kv = parts[0].split('=', 1)
      if kv.len == 2:
        var cObj = newJObject()
        cObj["name"] = %kv[0].strip()
        cObj["value"] = %kv[1].strip()

        var attrs = newJObject()
        for i in 1 ..< parts.len:
          let attrParts = parts[i].split('=', 1)
          let attrName = attrParts[0].strip().toLowerAscii()
          if attrParts.len == 2:
            attrs[attrName] = %attrParts[1].strip()
          else:
            attrs[attrName] = %true
        cObj["attributes"] = attrs
        jArr.add(cObj)

  return jArr.pretty()

