proc extractUniqueDomains(payload: string): string =
  let data = parseJson(payload)
  var domains = initHashSet[string]()

  proc traverse(node: JsonNode) =
    if node.kind == JString:
      let val = node.getStr()
      if val.startsWith("http"):
        try:
          let u = parseUri(val)
          if u.hostname.len > 0: domains.incl(u.hostname)
        except ValueError:
          discard
    elif node.kind == JArray:
      for child in node: traverse(child)
    elif node.kind == JObject:
      for _, child in node: traverse(child)

  traverse(data)

  var domainSeq: seq[string] = @[]
  for d in domains: domainSeq.add(d)

  return "Unique Domains:\n- " & domainSeq.join("\n- ")

