      if aStart == -1: break

      let hrefStart = html.toLowerAscii().find("href=\"", aStart)
      if hrefStart != -1:
        let hrefEnd = html.find("\"", hrefStart + 6)
        if hrefEnd != -1:
          let rawHref = html[hrefStart + 6 ..< hrefEnd]
          try:
            let absolute = baseUri / rawHref
            links.add(%($absolute))
          except ValueError:
            discard
          i = hrefEnd
      inc i
  except CatchableError:
    discard

  return links.pretty()

