  let confJson = parseFile(configFile)
  var client = newHttpClient()
  defer: client.close()

  var results = newJArray()

  for endpoint in confJson:
    let url = endpoint["url"].getStr()
    var rObj = newJObject()
    rObj["url"] = %url

    try:
      let resp = client.getContent(url)
      let jResp = parseJson(resp)
      if jResp.hasKey("ok") and jResp["ok"].kind == JBool and jResp["ok"].getBool():
        rObj["status"] = %"PASS"
      else:
        rObj["status"] = %"FAIL"
    except CatchableError:
      rObj["status"] = %"ERROR"

    results.add(rObj)

  var fs = newFileStream(resultFile, fmWrite)
  if not fs.isNil:
    fs.write(results.pretty())
    fs.close()

