import uri, strutils, json

proc generateWsUrls(httpUrls: seq[string], token: string): string =
  var jArr = newJArray()

  for uStr in httpUrls:
    try:
      var u = parseUri(uStr)
      if u.scheme == "http": u.scheme = "ws"
      elif u.scheme == "https": u.scheme = "wss"

      if u.query.len > 0:
        u.query = u.query & "&token=" & token
      else:
        u.query = "token=" & token

      jArr.add(%($u))
    except ValueError:
      continue

  return jArr.pretty()

