proc extractFtpLinks(url: string): string =
  var client = newHttpClient()
  defer: client.close()

  var jArr = newJArray()

  try:
    let html = client.getContent(url)
    var i = 0
    while i < html.len:
      let hrefStart = html.toLowerAscii().find("href=\"", i)
      if hrefStart == -1: break

      let hrefEnd = html.find("\"", hrefStart + 6)
      if hrefEnd != -1:
        let link = html[hrefStart + 6 ..< hrefEnd]
        if link.toLowerAscii().startsWith("ftp://"):
          jArr.add(%link)
        i = hrefEnd
      else:
        inc i
  except CatchableError:
    discard

  return jArr.pretty()

