import httpclient, strutils, streams

proc checkMarkdownLinks(mdText, outCsv: string) =
  var client = newHttpClient()
  client.timeout = 2000
  defer: client.close()

  var fsOut = newFileStream(outCsv, fmWrite)
  if fsOut.isNil: return
  defer: fsOut.close()

  fsOut.writeLine("url,status")

  var i = 0
  while i < mdText.len:
    let bracketStart = mdText.find("[", i)
    if bracketStart == -1: break
    let bracketEnd = mdText.find("](", bracketStart)
    if bracketEnd != -1:
      let parenEnd = mdText.find(")", bracketEnd + 2)
      if parenEnd != -1:
        let url = mdText[bracketEnd + 2 ..< parenEnd]
        if url.startsWith("http"):
          try:
            let resp = client.request(url, HttpHead)
            fsOut.writeLine(url & "," & $resp.code.int)
          except CatchableError:
            fsOut.writeLine(url & ",ERROR")
        i = parenEnd
      else: inc i
    else: inc i

