proc getDisallowedPaths(robotsUrl: string): string =
  var client = newHttpClient()
  defer: client.close()

  var disallowed = initHashSet[string]()
  let baseUri = parseUri(robotsUrl)

  try:
    let txt = client.getContent(robotsUrl)
    for line in txt.splitLines():
      let t = line.strip()
      if t.toLowerAscii().startsWith("disallow:"):
        let parts = t.split(":", 1)
        if parts.len == 2:
          let path = parts[1].strip()
          let fullUri = baseUri / path
          disallowed.incl($fullUri)
  except CatchableError:
    discard

  var jArr = newJArray()
  for p in disallowed: jArr.add(%p)
  return jArr.pretty()

