import asyncdispatch, httpclient, json

proc fetchLength(url: string): Future[tuple[u: string, len: int]] {.async.} =
  var client = newAsyncHttpClient()
  defer: client.close()
  try:
    let resp = await client.get(url)
    let body = await resp.body
    return (u: url, len: body.len)
  except CatchableError:
    return (u: url, len: -1)

proc aggregateLengths(urls: seq[string]): Future[string] {.async.} =
  var tasks: seq[Future[tuple[u: string, len: int]]] = @[]
  for u in urls:
    tasks.add(fetchLength(u))

  let results = await all(tasks)

  var j = newJObject()
  for r in results:
    j[r.u] = %r.len
  return j.pretty()

