proc generateNetInterfaces(configJson: string): string =
  let conf = parseJson(configJson)
  var res = "# Generated Network Configuration\n\n"

  res &= "auto lo\niface lo inet loopback\n\n"

  if conf.kind == JArray:
    for iface in conf:
      let name = iface["name"].getStr()
      let methodStr = iface["method"].getStr("dhcp")

      res &= "auto " & name & "\n"
      res &= "iface " & name & " inet " & methodStr & "\n"

      if methodStr == "static":
        res &= "    address " & iface["address"].getStr() & "\n"
        res &= "    netmask " & iface["netmask"].getStr() & "\n"
        if iface.hasKey("gateway"):
          res &= "    gateway " & iface["gateway"].getStr() & "\n"
      res &= "\n"

  return res

