proc parseHostsFile(content: string): string =
  var hostMap = initTable[string, string]()

  for line in content.splitLines():
    let t = line.strip()
    if t.len == 0 or t.startsWith("#"): continue

    let parts = t.splitWhitespace()
    if parts.len >= 2:
      let ip = parts[0]
      for i in 1 ..< parts.len:
        hostMap[parts[i]] = ip

  var j = newJObject()
  for host, ip in hostMap:
    j[host] = %ip
  return j.pretty()

