proc canonicalizeUrl(urlStr: string): string =
  try:
    var u = parseUri(urlStr)
    u.scheme = u.scheme.toLowerAscii()
    u.hostname = u.hostname.toLowerAscii()

    if u.query.len > 0:
      var params = u.query.split('&')
      params.sort()
      u.query = params.join("&")

    return $u
  except ValueError:
    return urlStr

