proc calculateEma(pricesJson: string, period: int): string =
  let arr = parseJson(pricesJson)
  var prices: seq[float] = @[]
  for a in arr: prices.add(a.getFloat())

  if prices.len == 0: return "[]"

  let alpha = 2.0 / float(period + 1)
  var emaSeq: seq[float] = @[prices[0]]
  var currentEma = prices[0]

  for i in 1 ..< prices.len:
    currentEma = (prices[i] * alpha) + (currentEma * (1.0 - alpha))
    emaSeq.add(currentEma)

  var jRes = newJArray()
  for e in emaSeq:
    jRes.add(%(formatFloat(e, ffDecimal, 2)))

  return jRes.pretty()

