proc rgbToHsl(r, g, b: int): tuple[h, s, l: float] =
  let rf = float(r) / 255.0
  let gf = float(g) / 255.0
  let bf = float(b) / 255.0

  let cMax = max(rf, max(gf, bf))
  let cMin = min(rf, min(gf, bf))
  let delta = cMax - cMin

  var l = (cMax + cMin) / 2.0
  var h, s: float = 0.0

  if delta > 0.0:
    s = if l < 0.5: delta / (cMax + cMin) else: delta / (2.0 - cMax - cMin)

    if cMax == rf: h = (gf - bf) / delta + (if gf < bf: 6.0 else: 0.0)
    elif cMax == gf: h = (bf - rf) / delta + 2.0
    else: h = (rf - gf) / delta + 4.0
    h /= 6.0

  return (h: h * 360.0, s: s * 100.0, l: l * 100.0)

proc generatePalette(size: int): string =
  var jArr = newJArray()

  for _ in 1..size:
    let r = rand(0..255)
    let g = rand(0..255)
    let b = rand(0..255)

    let hex = "#" & toHex(r, 2) & toHex(g, 2) & toHex(b, 2)
    let hsl = rgbToHsl(r, g, b)

    var obj = newJObject()
    obj["hex"] = %hex
    obj["hsl"] = %("hsl(" & $int(hsl.h) & "," & $int(hsl.s) & "%," & $int(hsl.l) & "%)")
    jArr.add(obj)

  return jArr.pretty()

