proc findClosestPoints(pointsJson: string): string =
  let arr = parseJson(pointsJson)
  var pts: seq[tuple[x, y: float]] = @[]
  for p in arr:
    pts.add((x: p[0].getFloat(), y: p[1].getFloat()))

  if pts.len < 2: return "{}"

  var minDistance = Inf
  var bestPair = (-1, -1)

  for i in 0 ..< pts.len:
    for j in i + 1 ..< pts.len:
      let dx = pts[i].x - pts[j].x
      let dy = pts[i].y - pts[j].y
      let dist = sqrt(dx*dx + dy*dy)

      if dist < minDistance:
        minDistance = dist
        bestPair = (i, j)

  var j = newJObject()
  j["min_distance"] = %minDistance
  j["point1"] = arr[bestPair[0]]
  j["point2"] = arr[bestPair[1]]
  return j.pretty()

