import json, strutils, math

proc parseTimeStr(t: string): int =
  let parts = t.split(":")
  if parts.len == 2:
    return parseInt(parts[0]) * 60 + parseInt(parts[1])
  return 0

proc findCommonFreeTime(scheduleJson: string): string =
  let arr = parseJson(scheduleJson)
  var busy = newSeq[bool](1440) # Minutes in a day

  for userSchedule in arr:
    for slot in userSchedule:
      let startM = parseTimeStr(slot["start"].getStr())
      let endM = parseTimeStr(slot["end"].getStr())
      for i in startM ..< endM:
        busy[i] = true

  var freeSlots = newJArray()
  var i = 0
  while i < 1440:
    if not busy[i]:
      let startFree = i
      while i < 1440 and not busy[i]: inc i
      let endFree = i

      var slot = newJObject()
      let sh = startFree div 60
      let sm = startFree mod 60
      let eh = endFree div 60
      let em = endFree mod 60
      slot["start"] = %($sh & ":" & intToStr(sm).align(2, '0'))
      slot["end"] = %($eh & ":" & intToStr(em).align(2, '0'))
      freeSlots.add(slot)
    else:
      inc i

  return freeSlots.pretty()

