proc simulateDistribution(distJson: string, trials: int): string =
  let dist = parseJson(distJson)
  var keys: seq[string] = @[]
  var cumProbs: seq[float] = @[]
  var sum = 0.0

  for k, v in dist:
    keys.add(k)
    sum += v.getFloat()
    cumProbs.add(sum)

  var counts = initCountTable[string]()
  for _ in 1..trials:
    let r = rand(1.0)
    for i, cp in cumProbs:
      if r <= cp:
        counts.inc(keys[i])
        break

  var jRes = newJObject()
  for k, v in dist:
    let expected = v.getFloat()
    let actual = float(counts.getOrDefault(k, 0)) / float(trials)

    var rObj = newJObject()
    rObj["expected"] = %expected
    rObj["actual"] = %actual
    rObj["error"] = %abs(expected - actual)
    jRes[k] = rObj

  return jRes.pretty()

