proc calculateRatesOfChange(dataJson: string): string =
  let arr = parseJson(dataJson)
  var points: seq[tuple[t: DateTime, v: float]] = @[]

  for p in arr:
    let ts = parse(p["ts"].getStr(), "yyyy-MM-dd'T'HH:mm:ss")
    let v = p["val"].getFloat()
    points.add((t: ts, v: v))

  points.sort(proc(a, b: tuple[t: DateTime, v: float]): int =
    if a.t < b.t: return -1
    if a.t > b.t: return 1
    return 0
  )

  var rates = newJArray()
  for i in 1 ..< points.len:
    let prev = points[i-1]
    let curr = points[i]
    let dt = float((curr.t - prev.t).inSeconds)
    var rate = 0.0
    if dt > 0.0:
      rate = (curr.v - prev.v) / dt

    var rObj = newJObject()
    rObj["from"] = %prev.t.format("HH:mm:ss")
    rObj["to"] = %curr.t.format("HH:mm:ss")
    rObj["rate_per_sec"] = %rate
    rates.add(rObj)

  return rates.pretty()

