import json, math, strutils

proc calculateAmortization(loanJson: string): string =
  let conf = parseJson(loanJson)
  let pOriginal = conf["principal"].getFloat()
  let annualRate = conf["rate"].getFloat()
  let months = conf["months"].getInt()

  let r = (annualRate / 100.0) / 12.0
  var pmt = 0.0
  if r > 0:
    let factor = pow(1.0 + r, float(months))
    pmt = pOriginal * (r * factor) / (factor - 1.0)
  else:
    pmt = pOriginal / float(months)

  var schedule = newJArray()
  var balance = pOriginal

  for m in 1..months:
    let interest = balance * r
    let principal = pmt - interest
    balance -= principal
    if balance < 0.0: balance = 0.0

    var row = newJObject()
    row["month"] = %m
    row["payment"] = %formatFloat(pmt, ffDecimal, 2)
    row["principal"] = %formatFloat(principal, ffDecimal, 2)
    row["interest"] = %formatFloat(interest, ffDecimal, 2)
    row["balance"] = %formatFloat(balance, ffDecimal, 2)
    schedule.add(row)

  return schedule.pretty()

