proc convertMdToHtmlStubs(dir: string) =
  for path in walkFiles(dir / "*.md"):
    var fsIn = newFileStream(path, fmRead)
    if fsIn.isNil: continue

    let base = splitFile(path).name
    let outPath = dir / base & ".html"

