    if fsOut.isNil:
      fsIn.close()
      continue

    fsOut.writeLine("<html><body>")
    var line = ""
    while fsIn.readLine(line):
      if line.startsWith("# "):
        fsOut.writeLine("<h1>" & line[2..^1] & "</h1>")
      elif line.startsWith("## "):
        fsOut.writeLine("<h2>" & line[3..^1] & "</h2>")
      else:
        fsOut.writeLine("<p>" & line & "</p>")
    fsOut.writeLine("</body></html>")

    fsIn.close()
