proc lockedWrite(targetFile, lockFile, data: string): string =
  var j = newJObject()
  var success = false

  for attempt in 1..3:
    if not fileExists(lockFile):
      # Create lock (race condition possible but ok for demo)
      writeFile(lockFile, "LOCKED")

      var fs = newFileStream(targetFile, fmAppend)
      if not fs.isNil:
        fs.writeLine(data)
        fs.close()
        success = true

      removeFile(lockFile)
      break
    else:
      sleep(100) # Wait 100ms

  j["written"] = %success
  return j.pretty()

