proc concatenateFiles(inputs: seq[string], output: string) =
  var fsOut = newFileStream(output, fmWrite)
  if fsOut.isNil: return
  defer: fsOut.close()

  var totalBytes = 0
  var buffer = newString(4096)

  for inFile in inputs:
    var fsIn = newFileStream(inFile, fmRead)
    if fsIn.isNil: continue

    while true:
      let bytesRead = fsIn.readData(addr buffer[0], 4096)
      if bytesRead > 0:
        fsOut.writeData(addr buffer[0], bytesRead)
        totalBytes += bytesRead
      if bytesRead < 4096:
        break
    fsIn.close()

  echo "Concatenated ", inputs.len, " files. Total size: ", totalBytes, " bytes."

