proc tailFile(filePath: string, n: int): seq[string] =
  let chunkSize = 4096
  var fs = newFileStream(filePath, fmRead)
  if fs.isNil: return @[]

  # Just read everything for simplicity in this example, 
  # a real tail would seek, but stdlib streams don't easily read backwards.
  let allText = fs.readAll()
  fs.close()

  let lines = allText.splitLines()
  var res: seq[string] = @[]

  let startIdx = max(0, lines.len - n - (if lines[^1] == "": 1 else: 0))
  for i in startIdx ..< lines.len:
    if lines[i].len > 0:
      res.add(lines[i])

  return res

