proc hashFileChunks(filePath: string): string =
  var fs = newFileStream(filePath, fmRead)
  if fs.isNil: return ""
  defer: fs.close()

  var ctx: MD5Context
  md5Init(ctx)

  var buffer = newString(8192)
  while true:
    let bytesRead = fs.readData(addr buffer[0], 8192)
    if bytesRead > 0:
      md5Update(ctx, addr buffer[0], bytesRead)
    if bytesRead < 8192:
      break

  var digest: MD5Digest
  md5Final(ctx, digest)
  return $digest

