proc parseApacheConf(confStr: string): string =
  var blocks = newJArray()
  var counts = initCountTable[string]()

  var inBlock = false
  var currentBlock = newJObject()

  for line in confStr.splitLines():
    let t = line.strip()
    if t.startsWith("<VirtualHost"):
      inBlock = true
      currentBlock = newJObject()
      let parts = t.splitWhitespace()
      if parts.len > 1:
        currentBlock["binding"] = %parts[1][0..^2]
        counts.inc(parts[1][0..^2])
    elif t.startsWith("</VirtualHost>"):
      inBlock = false
      blocks.add(currentBlock)
    elif inBlock and t.len > 0 and not t.startsWith("#"):
      let parts = t.splitWhitespace()
      if parts.len >= 2:
        currentBlock[parts[0].toLowerAscii()] = %parts[1..^1].join(" ")

  var res = newJObject()
  res["vhosts"] = blocks

  var jCounts = newJObject()
  for k, v in counts: jCounts[k] = %v
  res["bindings_summary"] = jCounts

  return res.pretty()

