import parseopt, json, times, os

proc handleTaskCommand(args: seq[string], dbPath: string): string =
  var p = initOptParser(args)
  var cmd = ""
  var taskName = ""

  for kind, key, val in p.getopt():
    if kind == cmdArgument:
      if cmd == "": cmd = key
      elif taskName == "": taskName = key

  var db = newJArray()
  if fileExists(dbPath):
    try: db = parseFile(dbPath)
    except JsonParsingError: discard

  if cmd == "add":
    if taskName != "":
      var t = newJObject()
      t["name"] = %taskName
      t["status"] = %"pending"
      t["created"] = %getTime().format("yyyy-MM-dd HH:mm:ss")
      db.add(t)
      writeFile(dbPath, db.pretty())
      return "Task added."
  elif cmd == "complete":
    for t in db:
      if t["name"].getStr() == taskName:
        t["status"] = %"completed"
        t["completed_at"] = %getTime().format("yyyy-MM-dd HH:mm:ss")
        writeFile(dbPath, db.pretty())
        return "Task completed."
    return "Task not found."
  elif cmd == "list":
    return db.pretty()

  return "Unknown command or missing arguments."

