proc extractIps(text: string): string =
  var ips = initHashSet[string]()

  for word in text.splitWhitespace():
    let parts = word.split('.')
    if parts.len == 4:
      var isIp = true
      for p in parts:
        try:
          let n = parseInt(p)
          if n < 0 or n > 255: isIp = false
        except ValueError: isIp = false
      if isIp:
        ips.incl(word)

  var jArr = newJArray()
  for ip in ips: jArr.add(%ip)
  return jArr.pretty()

