proc extractMdLists(mdText: string): string =
  var resultData = initTable[string, seq[string]]()
  var currentHeader = "default"

  for line in mdText.splitLines():
    let t = line.strip()
    if t.startsWith("### "):
      currentHeader = t[4..^1]
      if not resultData.hasKey(currentHeader):
        resultData[currentHeader] = @[]
    elif t.startsWith("- ") or t.startsWith("* "):
      if not resultData.hasKey(currentHeader):
        resultData[currentHeader] = @[]
      resultData[currentHeader].add(t[2..^1].strip())

  var j = newJObject()
  for h, list in resultData:
    var jArr = newJArray()
    for item in list: jArr.add(%item)
    j[h] = jArr

  return j.pretty()

