proc gcdMultiple(nums: seq[int]): int =
  if nums.len == 0: return 0
  result = nums[0]
  for i in 1 ..< nums.len:
    result = gcd(result, nums[i])

proc cliGcd(args: seq[string]): string =
  var p = initOptParser(args)
  var nums: seq[int] = @[]

  for kind, key, val in p.getopt():
    if kind == cmdArgument:
      try: nums.add(parseInt(key))
      except ValueError: discard

  var j = newJObject()
  j["numbers"] = newJArray()
  for n in nums: j["numbers"].add(%n)
  j["gcd"] = %gcdMultiple(nums)

  return j.pretty()

