import parsecsv, streams, strutils

proc csvToSqlUpdate(csvData, tableName, idCol: string): string =
  var s = newStringStream(csvData)
  var p: CsvParser
  p.open(s, "update.csv")
  p.readHeaderRow()

  var queries: seq[string] = @[]

  while p.readRow():
    let idVal = p.rowEntry(idCol)
    var setClauses: seq[string] = @[]

    for h in p.headers:
      if h != idCol:
        let val = p.rowEntry(h)
        setClauses.add(h & " = '" & val.replace("'", "''") & "'")

    let q = "UPDATE " & tableName & " SET " & setClauses.join(", ") & " WHERE " & idCol & " = '" & idVal & "';"
    queries.add(q)

  p.close()
  return queries.join("\n")

