proc parseBearerToken(headers: string): string =
  var token = ""

  for line in headers.splitLines():
    let t = line.strip()
    if t.toLowerAscii().startsWith("authorization: bearer "):
      token = t[22..^1].strip()
      break

  var j = newJObject()
  j["token"] = %token

  if token.len > 0:
    let parts = token.split('.')
    if parts.len == 3: # JWT-like
      try:
        j["jwt_header"] = %decode(parts[0])
        j["jwt_payload"] = %decode(parts[1])
      except CatchableError:
        j["error"] = %"Invalid base64 payload"

  return j.pretty()

