import os, md5, streams, sets, json

proc findDuplicateFiles(dir: string): string =
  var seenHashes = initHashSet[string]()
  var duplicates = newJArray()

  for path in walkDirRec(dir):
    var fs = newFileStream(path, fmRead)
    if not fs.isNil:
      var ctx: MD5Context
      md5Init(ctx)
      var buffer = newString(4096)
      while true:
        let b = fs.readData(addr buffer[0], 4096)
        if b > 0: md5Update(ctx, addr buffer[0], b)
        if b < 4096: break
      fs.close()

      var digest: MD5Digest
      md5Final(ctx, digest)
      let h = $digest

      if h in seenHashes:
        duplicates.add(%path)
      else:
        seenHashes.incl(h)

  var j = newJObject()
  j["duplicates_found"] = %duplicates.len
  j["files_to_delete"] = duplicates
  return j.pretty()

