proc jsonToIni(jsonStr, outPath: string) =
  let arr = parseJson(jsonStr)

  var fs = newFileStream(outPath, fmWrite)
  if fs.isNil: return
  defer: fs.close()

  for server in arr:
    let name = server["name"].getStr()
    fs.writeLine("[" & name & "]")

    for k, v in server:
      if k != "name":
        let valStr = if v.kind == JString: v.getStr() else: $v
        fs.writeLine(k & "=" & valStr)
    fs.writeLine("")

